.seat-row {
  display: grid;
  grid-template-columns: 2rem repeat(4, 2.2rem) 4.4rem repeat(16, 2.2rem) 4.4rem repeat(4, 2.2rem) 2rem;
  align-items: center;
  column-gap: 0.25rem;
  row-gap: 0.25rem;
  margin: 0.125rem 0;
}

.row-label {
  text-align: center;
  font-size: 0.85rem;
  color: #555;
}

.aisle {
  width: 100%;
}

.seat,
.couch {
  height: 2.2rem;
  border: none;
  border-radius: 4px;
  font-size: 0.75rem;
  cursor: pointer;
  padding: 0;

  &.state-available {
    background-color: #2e7d32;
    color: #fff;
  }

  &.state-selected {
    background-color: #f9a825;
    color: #000;
  }

  &.state-unavailable {
    background-color: #c62828;
    color: #fff;
    cursor: not-allowed;
  }

  &.state-accessible {
    background-color: #1565c0;
    color: #fff;
  }
}

.couch {
  font-size: 0.7rem;
}

