import { chromium } from 'playwright';

const errors = [];
const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(msg.text());
});
page.on('pageerror', (err) => errors.push('pageerror: ' + err.message));

async function shot(name) {
  await page.screenshot({ path: `/tmp/shots/${name}.png` });
}

await page.goto('http://localhost:4200/');
await page.waitForSelector('[data-testid="day-picker"]', { timeout: 10000 });
await page.waitForTimeout(500);
await shot('01-movie-list');

const movieCardCount = await page.locator('[data-testid="movie-card"]').count();
console.log('movie cards today:', movieCardCount);
const emptyVisible = await page.locator('[data-testid="movies-empty"]').count();
console.log('empty state:', emptyVisible);

// Choose a date with known screenings: 2026-09-15
await page.goto('http://localhost:4200/?date=2026-09-15');
await page.waitForSelector('[data-testid="movie-list"], [data-testid="movies-empty"]', { timeout: 10000 });
await shot('02-movie-list-0915');
const cards0915 = await page.locator('[data-testid="movie-card"]').count();
console.log('movie cards 2026-09-15:', cards0915);

const screeningButton = page.locator('[data-testid="screening-button"]').first();
const screeningId = await screeningButton.getAttribute('data-screening-id');
console.log('clicking screening', screeningId);
await screeningButton.click();
await page.waitForSelector('[data-testid="seat-map"]', { timeout: 10000 });
await page.waitForURL(/\/screenings\/\d+\/seats/);
await shot('03-seat-map');

const seatCount = await page.locator('[data-testid="seat"]').count();
const couchCount = await page.locator('[data-testid="couch"]').count();
console.log('seats:', seatCount, 'couches:', couchCount);

// select an available regular seat
const availSeat = page.locator('[data-testid="seat"][data-state="available"]').first();
await availSeat.click();
// select an available couch
const availCouch = page.locator('[data-testid="couch"][data-state="available"]').first();
await availCouch.click();
await page.waitForTimeout(200);
const countText = await page.locator('[data-testid="selected-seats-count"]').textContent();
console.log('selected count text:', countText);
await shot('04-selected');

// try to exceed limit: select 10 more available seats to trigger toast (we already have 3 selected: 1 seat + couch(2))
const availableSeats = page.locator('[data-testid="seat"][data-state="available"]');
const availableCount = await availableSeats.count();
for (let i = 0; i < Math.min(availableCount, 10); i++) {
  await availableSeats.nth(i).click();
  await page.waitForTimeout(50);
}
await page.waitForTimeout(300);
const toastVisible = await page.locator('[data-testid="toast"]').count();
console.log('toast visible after over-selecting:', toastVisible, toastVisible ? await page.locator('[data-testid="toast"]').textContent() : '');
await shot('05-limit-toast');

// Continue to summary
await page.locator('[data-testid="continue-button"]').click();
await page.waitForURL(/\/summary/);
await page.waitForSelector('[data-testid="summary-list"]');
await shot('06-summary');
const summaryItems = await page.locator('[data-testid="summary-item"]').count();
const total = await page.locator('[data-testid="summary-total"]').textContent();
console.log('summary items:', summaryItems, 'total:', total);

// Confirm to checkout
await page.locator('[data-testid="confirm-button"]').click();
await page.waitForURL(/\/checkout/);
await page.waitForSelector('[data-testid="checkout-title"]');
await shot('07-checkout-empty');

// click pay with empty form to see validation
await page.locator('[data-testid="pay-button"]').click();
await page.waitForTimeout(300);
const errorsShown = await page.locator('[data-testid$="-error"]').count();
console.log('validation errors shown:', errorsShown);
const toastInvalid = await page.locator('[data-testid="toast"]').textContent().catch(() => '');
console.log('toast invalid form:', toastInvalid);
await shot('08-checkout-invalid');

// fill form correctly
await page.fill('[data-testid="first-name-input"]', 'Anna');
await page.fill('[data-testid="last-name-input"]', 'Kowalska');
await page.fill('[data-testid="email-input"]', 'anna.kowalska@example.com');
await page.fill('[data-testid="confirm-email-input"]', 'anna.kowalska@example.com');
await page.fill('[data-testid="phone-input"]', '123456789');
await page.locator('[data-testid="terms-checkbox"]').click();
await page.waitForTimeout(200);
await shot('09-checkout-filled');

await page.locator('[data-testid="pay-button"]').click();
await page.waitForURL(/\/confirmation/, { timeout: 10000 });
await page.waitForSelector('[data-testid="confirmation-heading"]');
await shot('10-confirmation');
const confMsg = await page.locator('[data-testid="confirmation-message"]').textContent();
console.log('confirmation message:', confMsg);

await page.locator('[data-testid="confirmation-continue-button"]').click();
await page.waitForURL('http://localhost:4200/');
await page.waitForTimeout(300);
await shot('11-back-to-list');

console.log('CONSOLE ERRORS:', JSON.stringify(errors, null, 2));

await browser.close();

import { Component, input, output } from '@angular/core';
import { AuditoriumCell, AuditoriumRow } from '../../shared/auditorium';
import { seatId } from '../../shared/seat-utils';

@Component({
  selector: 'app-seat-row',
  templateUrl: './seat-row.component.html',
  styleUrl: './seat-row.component.scss',
})
export class SeatRowComponent {
  readonly row = input.required<AuditoriumRow>();
  readonly seatToggle = output<string[]>();

  protected cellKey(cell: AuditoriumCell): string {
    return cell.kind === 'seat' ? `seat-${cell.column}` : `couch-${cell.columnStart}`;
  }

  protected onCellClick(cell: AuditoriumCell): void {
    if (cell.state === 'unavailable') {
      return;
    }
    const ids = cell.kind === 'seat' ? [seatId(cell.row, cell.column)] : [seatId(cell.row, cell.columnStart), seatId(cell.row, cell.columnEnd)];
    this.seatToggle.emit(ids);
  }
}

