await page.fill('[data-testid="confirm-email-input"]', 'anna.kowalska@example.com');
await page.fill('[data-testid="phone-input"]', '123456789');
await page.locator('[data-testid="terms-checkbox"]').click();
await page.waitForTimeout(200);
await shot('09-checkout-filled');

await page.locator('[data-testid="pay-button"]').click();
await page.waitForURL(/\/confirmation/, { timeout: 10000 });
await page.waitForSelector('[data-testid="confirmation-heading"]');
await shot('10-confirmation');
const confMsg = await page.locator('[data-testid="confirmation-message"]').textContent();
console.log('confirmation message:', confMsg);

await page.locator('[data-testid="confirmation-continue-button"]').click();
await page.waitForURL('http://localhost:4200/');
await page.waitForTimeout(300);
await shot('11-back-to-list');

console.log('CONSOLE ERRORS:', JSON.stringify(errors, null, 2));

await browser.close();

