1	import { Component, computed, effect, inject, signal } from '@angular/core';
2	import { MatButtonModule } from '@angular/material/button';
3	import { MatCheckboxChange, MatCheckboxModule } from '@angular/material/checkbox';
4	import { MatFormFieldModule } from '@angular/material/form-field';
5	import { MatInputModule } from '@angular/material/input';
6	import { ActivatedRoute, Router } from '@angular/router';
7	import { ApiService } from '../../core/api.service';
8	import { BookingService } from '../../core/booking.service';
9	import { ToastService } from '../../core/toast.service';
10	import { CreateReservationPayload } from '../../core/models';
11	import { emptyForm } from '../../core/booking.model';
12	import { formatPrice } from '../../shared/seat-utils';
13	import { buildSummaryItems } from '../../shared/grouping';
14	
15	type FieldName = 'firstName' | 'lastName' | 'email' | 'confirmEmail' | 'phone' | 'termsAccepted';
16	
17	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
18	
19	@Component({
20	  selector: 'app-checkout',
21	  imports: [MatButtonModule, MatCheckboxModule, MatFormFieldModule, MatInputModule],
22	  templateUrl: './checkout.component.html',
23	  styleUrl: './checkout.component.scss',
24	})
25	export class CheckoutComponent {
26	  private readonly route = inject(ActivatedRoute);
27	  private readonly router = inject(Router);
28	  private readonly api = inject(ApiService);
29	  protected readonly bookingService = inject(BookingService);
30	  private readonly toast = inject(ToastService);
31	
32	  private readonly screeningId = Number(this.route.snapshot.paramMap.get('id'));
33	  private readonly initialForm = this.bookingService.booking()?.form ?? emptyForm();
34	
35	  protected readonly firstName = signal(this.initialForm.firstName);
36	  protected readonly lastName = signal(this.initialForm.lastName);
37	  protected readonly email = signal(this.initialForm.email);
38	  protected readonly confirmEmail = signal(this.initialForm.confirmEmail);
39	  protected readonly phone = signal(this.initialForm.phone);
40	  protected readonly termsAccepted = signal(this.initialForm.termsAccepted);
41	
42	  protected readonly touched = signal<Record<FieldName, boolean>>({
43	    firstName: false,
44	    lastName: false,
45	    email: false,
46	    confirmEmail: false,
47	    phone: false,
48	    termsAccepted: false,
49	  });
50	
51	  protected readonly submitting = signal(false);
52	
53	  protected readonly items = computed(() => buildSummaryItems(this.bookingService.booking()?.seats ?? []));
54	  protected readonly total = computed(() => this.items().reduce((sum, item) => sum + item.price, 0));
55	  protected readonly formatPrice = formatPrice;
56	
57	  protected readonly firstNameError = computed(() => requiredMinLength(this.firstName(), 'First name', 2));
58	  protected readonly lastNameError = computed(() => requiredMinLength(this.lastName(), 'Last name', 2));
59	
60	  protected readonly emailError = computed(() => {
61	    const value = this.email();
62	    if (!value) {
63	      return 'Email is required';
64	    }
65	    return EMAIL_RE.test(value) ? null : 'Enter a valid email address';
66	  });
67	
68	  protected readonly confirmEmailError = computed(() => {
69	    const value = this.confirmEmail();
70	    if (!value) {
71	      return 'Confirm email is required';
72	    }
73	    return value === this.email() ? null : 'Email addresses do not match';
74	  });
75	
76	  protected readonly phoneError = computed(() => {
77	    const value = this.phone();
78	    if (!value) {
79	      return null;
80	    }
81	    return /^\d{9}$/.test(value) ? null : 'Phone number must be exactly 9 digits';
82	  });
83	
84	  protected readonly termsError = computed(() => (this.termsAccepted() ? null : 'You must accept the terms and conditions'));
85	
86	  protected readonly formValid = computed(
87	    () =>
88	      !this.firstNameError() &&
89	      !this.lastNameError() &&
90	      !this.emailError() &&
91	      !this.confirmEmailError() &&
92	      !this.phoneError() &&
93	      !this.termsError(),
94	  );
95	
96	  constructor() {
97	    effect(() => {
98	      this.bookingService.updateForm({
99	        firstName: this.firstName(),
100	        lastName: this.lastName(),
101	        email: this.email(),
